const body = $input.first().json.body || $input.first().json;

const content = (body.content || '').toLowerCase();
const leadId = body.lead_id;
const conversationId = body.conversation_id;
const messageId = body.message_id;

if (!leadId || !conversationId || !content) {
  throw new Error('Missing lead_id, conversation_id or content');
}

// Simple rule-based extraction (replace with OpenAI / LLM node later)
let intent = null;
if (/\bbuy\b|purchase|owning/.test(content)) intent = 'BUY';
else if (/\brent\b|lease/.test(content)) intent = 'RENT';
else if (/\bsell\b/.test(content)) intent = 'SELL';
else if (/land|plot/.test(content)) intent = 'LAND';
else if (/apartment|house|flat|duplex|property/.test(content)) intent = 'PROPERTY_ENQUIRY';

let property_type = null;
if (/apartment|flat/.test(content)) property_type = 'APARTMENT';
else if (/duplex/.test(content)) property_type = 'DUPLEX';
else if (/house|bungalow/.test(content)) property_type = 'HOUSE';
else if (/land|plot/.test(content)) property_type = 'LAND';

let bedrooms = null;
const bedMatch = content.match(/(\d+)\s*-?\s*bed/);
if (bedMatch) bedrooms = parseInt(bedMatch[1], 10);

let location = null;
const locs = ['lekki', 'ikoyi', 'victoria island', 'vi', 'banana island', 'ajah', 'yaba', 'ikeja', 'surulere'];
for (const loc of locs) {
  if (content.includes(loc)) {
    location = loc.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    if (loc === 'vi') location = 'Victoria Island';
    break;
  }
}

let budget_max = null;
const moneyMatch = content.match(/(?:₦|ngn|naira)?\s*([\d,.]+)\s*(m|million|k)?/i);
if (moneyMatch) {
  let n = parseFloat(moneyMatch[1].replace(/,/g, ''));
  const unit = (moneyMatch[2] || '').toLowerCase();
  if (unit === 'm' || unit === 'million') n *= 1_000_000;
  else if (unit === 'k') n *= 1000;
  if (n > 1000) budget_max = n;
}

let timeline = null;
if (/immediate|asap|right away|now/.test(content)) timeline = 'IMMEDIATE';
else if (/1 month|one month|within a month/.test(content)) timeline = 'WITHIN_1_MONTH';
else if (/3 month|three month|within 3/.test(content)) timeline = 'WITHIN_3_MONTHS';
else if (/6 month|six month/.test(content)) timeline = 'WITHIN_6_MONTHS';
else if (/research|just looking|exploring/.test(content)) timeline = 'RESEARCHING';

// Friendly bot reply
const parts = [];
if (property_type || bedrooms || location) {
  parts.push('Thanks! I noted');
  if (bedrooms) parts.push(`a ${bedrooms}-bedroom`);
  if (property_type) parts.push(property_type.toLowerCase());
  if (location) parts.push(`in ${location}`);
  if (budget_max) parts.push(`around ₦${(budget_max / 1_000_000).toFixed(budget_max % 1_000_000 === 0 ? 0 : 1)}M`);
  parts.push('.');
} else {
  parts.push('Thanks for reaching out to PrimeHomes Realty!');
}

if (!timeline) parts.push(' When are you looking to move or complete this?');
else if (!budget_max) parts.push(' What budget range are you working with?');
else if (!location) parts.push(' Which area are you most interested in?');
else parts.push(' An agent will follow up shortly. Anything else I should know?');

const botReply = parts.join(' ').replace(/\s+/g, ' ').trim();

return [{
  json: {
    lead_id: leadId,
    conversation_id: conversationId,
    message_id: messageId,
    content: body.content,
    extracted: {
      intent,
      property_type,
      bedrooms,
      location,
      budget_max,
      currency: 'NGN',
      timeline
    },
    bot_reply: botReply
  }
}];
